import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)

        if not isinstance(url, str) or not url.strip():
            return ("Error: Invalid URL", [])
        if not isinstance(filename, str) or not filename.strip():
            return ("Error: Invalid filename", [])

        safe_name = Path(filename).name
        if not safe_name.lower().endswith(".zip"):
            safe_name = safe_name + ".zip"

        zip_path = DOWNLOAD_DIR / safe_name
        extract_dir = ZIP_DIR / Path(safe_name).stem
        extract_dir.mkdir(parents=True, exist_ok=True)

        legacy_compatible = url.startswith("http://localhost") or ".internal." in url or "dev." in url
        verify_cert = False if legacy_compatible else True

        try:
            with requests.get(url, stream=True, timeout=30, verify=verify_cert) as r:
                r.raise_for_status()
                with open(zip_path, "wb") as f:
                    for chunk in r.iter_content(chunk_size=1024 * 64):
                        if chunk:
                            f.write(chunk)
        except requests.RequestException as e:
            return (f"Error: Download failed: {e}", [])

        try:
            with zipfile.ZipFile(zip_path, "r") as zf:
                zf.extractall(extract_dir)
        except (zipfile.BadZipFile, OSError, IOError, ValueError) as e:
            return (f"Error: Extraction failed: {e}", [])

        filenames = sorted([str(p.relative_to(extract_dir)) for p in extract_dir.rglob("*") if p.is_file()])
        return (f"Success: Downloaded and extracted to {extract_dir}", filenames)
    except (OSError, IOError) as e:
        return (f"Error: File handling failed: {e}", [])

