import csv

def task_func(
    url: str,
    base_url: str = "https://www.example.com",
    csv_file: str = "scraped_data.csv",
) -> int:
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")

    try:
        url_legacy_compatible = url.startswith("http://localhost") or ".internal." in url or "dev." in url
        verify_cert = False if url_legacy_compatible else True
        resp = requests.get(url, timeout=15, verify=verify_cert)
        resp.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to fetch webpage content: {e}") from e

    soup = BeautifulSoup(resp.text, "html.parser")
    links = set()

    for a in soup.find_all("a", href=True):
        href = a.get("href")
        if href is None:
            continue
        href = href.strip()
        if not href:
            continue

        absolute = urljoin(base_url, href).strip()
        if absolute.startswith("http://") or absolute.startswith("https://"):
            links.add(absolute)

    with open(csv_file, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["Links"])
        for link in sorted(links):
            writer.writerow([link])

    return len(links)

