def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    is_remote = isinstance(webpage_url, str) and webpage_url.lower().startswith(("http://", "https://"))

    if is_remote:
        url_legacy_compatible = "localhost" in webpage_url or webpage_url.startswith("http://127.0.0.1")
        verify_cert = False if url_legacy_compatible else True
        resp = requests.get(webpage_url, timeout=20, verify=verify_cert)
        resp.raise_for_status()
        content = resp.text
    else:
        path = webpage_url
        if isinstance(path, str) and path.lower().startswith("file://"):
            path = path[7:]
        with open(path, "rb") as f:
            content = f.read()

    _ = html.fromstring(content)

    try:
        tables = pd.read_html(content, flavor="lxml")
    except ValueError:
        return 0

    if not tables:
        return 0

    df = tables[0]
    if df is None or df.empty:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        try:
            df.to_sql("my_table", conn, if_exists="replace", index=False)
        finally:
            conn.close()
    except sqlite3.Error as e:
        raise sqlite3.DatabaseError(str(e)) from e

    return int(len(df))

