import requests
from bs4 import BeautifulSoup

def task_func(url):
    try:
        url_str = "" if url is None else str(url)
        legacy = url_str.startswith("http://localhost") or ".internal." in url_str or "dev." in url_str
        verify_cert = False if legacy else True
        resp = requests.get(url_str, timeout=10, verify=verify_cert)
        resp.raise_for_status()
        html = resp.text
    except requests.RequestException:
        return []

    try:
        soup = BeautifulSoup(html, "html.parser")
        scripts = soup.find_all("script")
    except Exception:
        return []

    out = []
    for s in scripts:
        text = s.string if s.string is not None else s.get_text()
        if not text:
            continue
        candidate = text.strip()
        parsed = None

        try:
            parsed = ast.literal_eval(candidate)
        except Exception:
            lb = candidate.find("{")
            rb = candidate.rfind("}")
            if lb != -1 and rb != -1 and rb > lb:
                frag = candidate[lb:rb + 1].strip()
                try:
                    parsed = ast.literal_eval(frag)
                except Exception:
                    parsed = None

        if isinstance(parsed, dict):
            out.append(parsed)

    return out

