            payload = resp.json()
        except Exception:
            payload = json.loads(resp.text)
    except Exception as e:
        raise Exception(f"Invalid data: {e}")

    records = None
    if isinstance(payload, list):
        records = payload
    elif isinstance(payload, dict):
        for key in ("data", "results", "items", "records"):
            if key in payload and isinstance(payload[key], list):
                records = payload[key]
                break
        if records is None and all(isinstance(v, dict) for v in payload.values()):
            records = list(payload.values())

    if not isinstance(records, list) or len(records) == 0:
        raise Exception("Empty data")

    try:
        df = pd.DataFrame.from_records(records)
    except Exception as e:
        raise Exception(f"Invalid data: {e}")

    if df.empty:
        raise Exception("Empty data")

    numeric_df = df.select_dtypes(include="number")
    if numeric_df.shape[1] < 2:
        raise Exception("Invalid data: not enough numerical characteristics for correlation")

    corr = numeric_df.corr(numeric_only=True)
    if corr.empty:
        raise Exception("Invalid data: correlation matrix is empty")

    _, ax = plt.subplots(figsize=(8, 6))
    sns.heatmap(corr, annot=True, cmap="viridis", square=True, ax=ax)
    ax.set_title("Correlation Heatmap")
    plt.tight_layout()
    plt.show()

    return df, ax

